<?php require_once __DIR__.'/../config/config.php';require_admin();$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']);$slug=slugify($name);$pdo->prepare('INSERT INTO categories(name,slug) VALUES(?,?)')->execute([$name,$slug]);flash('ok','Categoria criada.');redirect('categories.php');}$rows=$pdo->query('SELECT c.*,COUNT(p.id) products FROM categories c LEFT JOIN products p ON p.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();require __DIR__.'/includes/header.php';?><div class="content"><h1>Categorias</h1><div class="panel" style="margin:20px 0"><form class="actions" method="post"><?=csrf_field()?><input name="name" placeholder="Nome da categoria" required><button class="btn">Adicionar</button></form></div><div class="panel"><table class="table"><tr><th>Categoria</th><th>Slug</th><th>Produtos</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['slug'])?></td><td><?=e($r['products'])?></td></tr><?php endforeach;?></table></div></div><?php require __DIR__.'/includes/footer.php';
